package localmesh

import (
	"bytes"
	"encoding/hex"
	"slices"
	"testing"
	"time"

	"github.com/wendylabsinc/wendy/go/internal/agent/netwire"
)

// Generated by Lite wn_manifest_capabilities_write with UUID 4444..., route
// router 42/seq 7, revision 1, a 60-second lease, native 5054/app 43022, and sensors.
// The exact C bytes are decoded by Go and reproduce deterministically, without
// a separate service catalogue record or any encoding translation.
func TestLiteNativeAgentCBORFixture(t *testing.T) {
	const fixture = ""
	encoded, err := hex.DecodeString(fixture)
	if err != nil {
		t.Fatal(err)
	}
	manifest, err := DecodeManifest(encoded)
	if err != nil {
		t.Fatal(err)
	}
	if err := manifest.validate(time.UnixMilli(1800000000000)); err != nil {
		t.Fatal(err)
	}
	if manifest.Platform != PlatformLite || manifest.Name != "Lab C5" || !slices.Equal(manifest.Caps, []string{CapabilitySensors}) || manifest.AgentTransport != AgentMTLS || manifest.AgentPort != 5054 {
		t.Fatalf("Lite native metadata: %+v", manifest)
	}
	reencoded, err := netwire.Marshal(manifest)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(encoded, reencoded) {
		t.Fatalf("C/Go canonical metadata differ:\nC: %x\nGo: %x", encoded, reencoded)
	}
}

func TestNativeAgentMetadataSignedRosterRoundTrip(t *testing.T) {
	directory, chain, key, device, now := directoryFixture(t)
	manifest := routeManifest(device, now)
	manifest.AgentTransport = AgentMTLS
	manifest.AgentPort = 5054
	manifest.Platform = PlatformLite
	manifest.Caps = []string{"example-provider", CapabilitySensors}
	wire, err := SignManifest(manifest, chain, key, now)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := netwire.Marshal(wire)
	if err != nil {
		t.Fatal(err)
	}
	var received SignedManifest
	if err := netwire.Unmarshal(encoded, &received); err != nil {
		t.Fatal(err)
	}
	if _, err := directory.Accept(received, now); err != nil {
		t.Fatal(err)
	}
	got := directory.Snapshot(now)
	if len(got) != 1 || got[0].Platform != PlatformLite || !slices.Equal(got[0].Caps, manifest.Caps) || got[0].AgentPort != 5054 || got[0].AgentTransport != AgentMTLS {
		t.Fatalf("native metadata lost from signed roster: %+v", got)
	}
	got[0].Caps[0] = "local-view-change"
	if !slices.Equal(directory.Snapshot(now)[0].Caps, manifest.Caps) {
		t.Fatal("snapshot capability storage aliases directory")
	}
	var body map[string]netwire.RawMessage
	if err := netwire.Unmarshal(received.Body, &body); err != nil {
		t.Fatal(err)
	}
	platform, _ := netwire.Marshal(PlatformLite)
	caps, _ := netwire.Marshal(manifest.Caps)
	if !bytes.Equal(body[netwire.Key("platform")], platform) || !bytes.Equal(body[netwire.Key("caps")], caps) {
		t.Fatalf("native CBOR field mapping: %+v", body)
	}
}
